const fs = require("fs");
const envText = fs.readFileSync("/Users/trainguyen/Documents/work/rule-service/.run.local.env", "utf8");
const uriLine = envText.split("\n").find(l => l.startsWith("MONGO_URI="));
const uri = uriLine.split("=").slice(1).join("=").trim();
const mongoose = require("/Users/trainguyen/Documents/work/centralized-export-service/node_modules/mongoose");
(async () => {
  const conn = await mongoose.createConnection(uri).asPromise();
  const domains = await conn.db.collection("domains").find({ isDelete: false }).toArray();
  const routingRules = await conn.db.collection("rules").find({ ruleType: "routing", isDelete: false }).toArray();
  console.log("DOMAINS:", JSON.stringify(domains, null, 2));
  console.log("ROUTING_RULES:", JSON.stringify(routingRules, null, 2));
  await conn.close();
})();
